  "claims": [
    {
      "claim": "Fed-state human absolute oral bioavailability for small heteroaromatic drugs is consistently above 20%: ziprasidone approximately 59-60% at 20 mg with high-fat/fed conditions, and trazodone 63-65% after food.",
      "card_ids": ["C05","C10","C13","C06","C11","C12","C21","C24","C02","C25","C26"]
    },
    {
      "claim": "Other small-molecule oral drugs also exceed 20%: urapidil 72-78%, DPP-4 inhibitors/teneligliptin 43-87%, eltrombopag 52%, and ondansetron 40% even under rifampin co-treatment.",
      "card_ids": ["C01","C04","C09","C17","C22","C30","C08","C20","C27","C18","C23","C03","C19","C28"]
    },
    {
      "claim": "Low or variable records are structurally distant or condition-mismatched: TFMPP low bioavailability was inferred from <1% urinary recovery, brexanolone is <5%, and mCPP ranges 12-108% with wide variability; none provides affirmative transferable evidence for F < 20% in this small neutral pyrazolone.",
      "card_ids": ["C14","C16","C15","C29"]
    },
    {
      "claim": "L3 oral AUC/Cmax records for phenobarbital, pirfenidone, and ketoprofen show measurable oral exposure and food effects but lack IV-comparator absolute F data for the query and are not pyrazolones; they do not alter the prediction.",
      "card_ids": ["C31","C32","C33","C34","C35","C36","C37","C38","C39","C40","C41","C42"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C31","C32","C33","C34","C35","C36","C37","C38","C39","C40","C41","C42"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement is available for the query molecule itself.",
    "No query-specific fed-state pharmacokinetic or IV-comparator AUC data are provided.",
    "No direct query-specific solubility, dissolution, or first-pass extraction data are available.",
    "Transfer relies on structurally related but not identical molecules; no close structural analogue with a direct F measurement is present.",
    "L3 exposure records are for phenobarbital, pirfenidone, and ketoprofen, not for the query pyrazolone, and do not provide absolute F values."
  ],
  "decision_summary": "Prediction remains high: the query is a small neutral pyrazolone with favorable physicochemical properties for absorption, and the available fed-state and general human oral bioavailability records for small heteroaromatic drugs consistently exceed the 20% threshold. Low or variable records are structurally distant or condition-mismatched and do not affirm F < 20%. L3 oral exposure records do not change the decision. Confidence is moderate because no direct query-specific F measurement is available."
}

